// #ad36ca (6a6215b6) — TC-DIST-01..05: distance chip "NN.N KM" in search rows, partner profile, own profile, sort by distance, job search.
// Read-only: nothing is created or changed. iOS: never tap by coordinates (phone/WhatsApp buttons sit in every row);
// scrolling uses 'mobile: scroll' / 'mobile: scrollGesture', taps only on elements.
import assert from 'node:assert/strict';
import { startDriver, byText, search, goTab, openLink, SHARE_BASE, PARTNER, USERS, IS_IOS, APP_ID } from '../lib/session.js';

const ME = IS_IOS ? USERS.ios : USERS.android;
const KM_RE = /^\s*(\d+(?:\.\d+)?|-{3})\s*KM\s*$/;     // whole label of the chip: "15.1 KM" | "--- KM"
const NUM_RE = /^\d+\.\d$/;                              // real value, one decimal (e.g. 85.7)

/** Visible distance chips, top-to-bottom: [{ v: number|null, raw, y }]. null = "--- KM". */
async function kmChips(d) {
  const els = IS_IOS
    ? await d.$$('-ios predicate string:type == "XCUIElementTypeStaticText" AND label CONTAINS "KM"')
    : await d.$$('//android.widget.TextView[contains(@text,"KM")]');
  const out = [];
  for (const el of els) {
    if (!(await el.isDisplayed().catch(() => false))) continue;
    const raw = IS_IOS ? await el.getAttribute('label') : await el.getText();
    const m = KM_RE.exec(raw || '');
    if (!m) continue;
    const { y } = await el.getLocation();
    out.push({ v: m[1] === '---' ? null : Number(m[1]), num: m[1], raw, y });
  }
  return out.sort((a, b) => a.y - b.y);
}

async function waitChips(d, timeout = 20000) {
  let chips = [];
  await d.waitUntil(async () => (chips = await kmChips(d)).length > 0,
    { timeout, interval: 1000, timeoutMsg: 'no distance chips ("… KM") on screen' });
  return chips;
}

/** Scroll the list without touching row buttons. Returns false when nothing new appeared. */
async function scrollDown(d) {
  if (IS_IOS) await d.execute('mobile: scroll', { direction: 'down' });
  else {
    const { width, height } = await d.getWindowSize();
    await d.execute('mobile: scrollGesture', {
      left: Math.round(width * 0.1), top: Math.round(height * 0.35), width: Math.round(width * 0.8), height: Math.round(height * 0.45),
      direction: 'down', percent: 0.8,
    });
  }
}

async function restartApp(d) {
  await d.terminateApp(APP_ID);
  await d.activateApp(APP_ID);
  await (await byText(d, 'חיפוש')).waitForDisplayed({ timeout: 30000 });
}

describe('Distance indicator #ad36ca @ios @android @prod-safe', function () {
  let d;
  before(async () => { d = await startDriver(); });
  after(async () => { if (d) await d.deleteSession(); });

  it('TC-DIST-01: workers search in Hebrew — no constant "3.5 KM", at least one real "NN.N KM"', async () => {
    await search(d, 'עובדים', 'פועל כללי');
    const chips = await waitChips(d);
    const raws = chips.map((c) => c.raw);
    assert.ok(!chips.some((c) => c.v === 3.5), `constant 3.5 KM must be gone, got ${raws}`);
    assert.ok(chips.some((c) => c.v !== null && NUM_RE.test(c.num)), `at least one row must show a real distance, got ${raws}`);
  });

  it('TC-DIST-04: sort "מרחק (מהקרוב)" — ascending, "--- KM" only at the end', async () => {
    await search(d, 'עובדים', 'פועל כללי');
    await waitChips(d);
    await (await byText(d, 'מיין תוצאות לפי', true)).click();
    const opt = await byText(d, 'מרחק (מהקרוב)', true);
    await opt.waitForDisplayed({ timeout: 10000 });
    await opt.click();
    await d.waitUntil(async () => !(await opt.isDisplayed().catch(() => false)), { timeout: 10000, timeoutMsg: 'sort sheet did not close' });
    // wait until the first visible chip is the smallest one on screen (list re-rendered sorted)
    let first = [];
    await d.waitUntil(async () => {
      first = await kmChips(d);
      const nums = first.filter((c) => c.v !== null).map((c) => c.v);
      return nums.length > 0 && first[0].v === Math.min(...nums);
    }, { timeout: 20000, interval: 1000, timeoutMsg: 'list did not re-sort by distance' });

    let maxSeen = -Infinity; let dashSeen = false; let prevSig = ''; const all = [];
    for (let i = 0; i < 8; i++) {
      const chips = i === 0 ? first : await kmChips(d);
      const sig = chips.map((c) => c.raw).join('|');
      if (i > 0 && sig === prevSig) break;                       // end of list
      prevSig = sig;
      for (const c of chips) {
        all.push(c.raw);
        if (c.v === null) { dashSeen = true; continue; }
        assert.ok(!dashSeen, `number after "--- KM" — dashes must be last: ${all}`);
        assert.ok(c.v >= maxSeen, `not ascending: ${c.v} after ${maxSeen} (${all})`);
        maxSeen = c.v;
      }
      await scrollDown(d);
    }
    assert.ok(maxSeen > -Infinity, `no numeric distances after sorting: ${all}`);
  });

  it('TC-DIST-02: partner profile shows straight-line distance בת ים↔באר שבע ≈ 85.7 (84–88)', async () => {
    await openLink(d, SHARE_BASE + PARTNER.id);
    await (await byText(d, PARTNER.name)).waitForDisplayed({ timeout: 30000 });
    const chips = await waitChips(d);
    const c = chips[0];
    assert.ok(c.v !== null && NUM_RE.test(c.num), `profile chip must be "NN.N KM", got "${c.raw}"`);
    assert.ok(c.v >= 84 && c.v <= 88, `expected ≈85.7 KM (84–88), got ${c.v}`);
  });

  it('TC-DIST-03: own profile ("פרופיל") has no distance chip', async () => {
    await restartApp(d);                                           // 26.10: own profile could hang loading without a restart
    await goTab(d, 'פרופיל');
    await (await byText(d, ME.name)).waitForDisplayed({ timeout: 30000 });
    await (await byText(d, 'VFM', true)).waitForDisplayed({ timeout: 15000 });  // header chips rendered
    const kmAny = IS_IOS
      ? await d.$$('-ios predicate string:label CONTAINS " KM" OR label ENDSWITH "KM"')
      : await d.$$('//*[contains(@text,"KM") or contains(@content-desc,"KM")]');
    const shown = [];
    for (const el of kmAny) if (await el.isDisplayed().catch(() => false)) shown.push(IS_IOS ? await el.getAttribute('label') : await el.getText());
    assert.equal(shown.length, 0, `own profile must not show distance, got ${shown}`);
  });

  it('TC-DIST-05: job search in Hebrew — ads show real distances, not all "--- KM"', async () => {
    await search(d, 'עבודה', 'פועל כללי');
    const chips = await waitChips(d);
    const raws = chips.map((c) => c.raw);
    assert.ok(!chips.some((c) => c.v === 3.5), `constant 3.5 KM must be gone, got ${raws}`);
    assert.ok(chips.some((c) => c.v !== null && NUM_RE.test(c.num)), `not all ads may be "--- KM", got ${raws}`);
  });
});
